solution.solution.py:
NAMES = ["HALT", "LOAD", "ADD", "SUB", "STORE", "JUMP", "JUMPZ"]

def decode(code):
    op, address = code // 100, code % 100
    return (NAMES[op] if op < len(NAMES) else "???", address)

def encode(name, address):
    return NAMES.index(name) * 100 + address

unitTests:
@test("decoding")
def _():
    check_eq(decode(110), ("LOAD", 10))
    check_eq(decode(211), ("ADD", 11))
    check_eq(decode(412), ("STORE", 12))
    check_eq(decode(605), ("JUMPZ", 5))
    check_eq(decode(0), ("HALT", 0))

@test("unknown operations")
def _():
    check_eq(decode(712), ("???", 12))
    check_eq(decode(999), ("???", 99))

@test("encoding, and there and back")
def _():
    check_eq(encode("STORE", 12), 412)
    check_eq(encode("JUMP", 1), 501)
    check_eq(encode("HALT", 0), 0)
    for code in [110, 211, 311, 412, 501, 605]:
        check_eq(encode(*decode(code)), code)

